#!/usr/bin/env node
/**
 * @fileoverview Prisma matrix gate: runs the store's own end-to-end specs against the built `./prisma` bundle with
 * a client generated by a given Prisma major and generator.
 * @layer scripts
 *
 * The `./prisma` subpath works with the client the host passes it, so what a host sees depends on the major
 * (6 or 7) and on the generator (`prisma-client-js`, or `prisma-client` with a custom `output`, which Prisma 7
 * requires). The repository's own suite runs against one of the four combinations only. This gate installs the
 * client of one combination in a scratch directory, generates it there, and runs the specs that carry the ledger,
 * the wallet, the budget, the replay path and the time-zone behaviour against a Testcontainers PostgreSQL, with
 * `@prisma/client` mapped to the generated client and the package entry points mapped to `dist/`. Nothing is
 * installed in the repository.
 *
 * Usage: `node scripts/prisma-matrix.mjs <cell>` after `pnpm build`, where the cell is one of `p6-js`,
 * `p6-custom`, `p7-js` or `p7-custom`. Needs network (npm) and Docker.
 */
import { spawnSync } from 'node:child_process'
import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..')
const WORK = join(process.env.RUNNER_TEMP ?? tmpdir(), 'prisma-matrix')

/** The specs a cell runs: the store against a real database, including the zone-sensitive ones. */
const SPECS = [
  'prisma-migrations',
  'prisma-wallet-budget',
  'usage-time-zone',
  'price-time-zone',
  'wallet-time-zone',
  'budget-time-zone',
  'record-replay',
]

/** The combinations, with exact versions so a run means the same thing each time. */
const CELLS = {
  'p6-js': { major: 6, version: '6.19.3', generator: 'prisma-client-js', custom: false },
  'p6-custom': { major: 6, version: '6.19.3', generator: 'prisma-client', custom: true },
  'p7-js': { major: 7, version: '7.10.1', generator: 'prisma-client-js', custom: false },
  'p7-custom': { major: 7, version: '7.10.1', generator: 'prisma-client', custom: true },
}

/** Runs a command and returns its result without throwing on a non-zero exit. */
function run(command, args, cwd, env = {}) {
  return spawnSync(command, args, { cwd, encoding: 'utf8', env: { ...process.env, ...env }, maxBuffer: 1 << 28 })
}

/** The Prisma schema of a cell: the shipped models plus the generator and datasource of that combination. */
function schemaOf(cell) {
  const fragment = readFileSync(join(ROOT, 'src/prisma/schema.prisma.fragment'), 'utf8')
  const output = cell.custom ? '  output = "./generated/prisma"\n  moduleFormat = "cjs"\n' : ''
  const url = cell.major === 6 ? '  url = env("DATABASE_URL")\n' : ''
  return `generator client {\n  provider = "${cell.generator}"\n${output}}\n\ndatasource db {\n  provider = "postgresql"\n${url}}\n\n${fragment}\n`
}

/** The module that exports `PrismaClient` for a cell. */
function clientModule(dir, cell) {
  return cell.custom ? join(dir, 'prisma/generated/prisma/client') : join(dir, 'node_modules/@prisma/client')
}

/**
 * Writes the shims and the Jest configuration of a cell. Prisma 6 has no driver adapter by default, so its shim
 * opens the client from the connection string the specs give the adapter.
 */
function writeHarness(dir, cell) {
  writeFileSync(
    join(dir, 'shim-client.cjs'),
    `const real = require(${JSON.stringify(clientModule(dir, cell))})
class PrismaClient extends real.PrismaClient {
  constructor(options = {}) {
    if (${cell.major} === 6 && options.adapter) super({ datasourceUrl: options.adapter.connectionString })
    else super(options)
  }
}
module.exports = { ...real, PrismaClient }
`,
  )
  writeFileSync(
    join(dir, 'shim-adapter.cjs'),
    cell.major === 6
      ? 'class PrismaPg { constructor(config) { this.connectionString = config.connectionString } }\nmodule.exports = { PrismaPg }\n'
      : `module.exports = require(${JSON.stringify(join(dir, 'node_modules/@prisma/adapter-pg'))})\n`,
  )
  const dist = join(ROOT, 'dist')
  writeFileSync(
    join(dir, 'jest.config.cjs'),
    `module.exports = {
  rootDir: ${JSON.stringify(ROOT)},
  testEnvironment: 'node',
  roots: [${JSON.stringify(join(ROOT, 'test/e2e'))}],
  testMatch: ${JSON.stringify(SPECS.map((spec) => join(ROOT, `test/e2e/${spec}.e2e-spec.ts`)))},
  transform: { '^.+\\\\.[tj]sx?$': ['ts-jest', { tsconfig: ${JSON.stringify(join(ROOT, 'tsconfig.jest.json'))}, diagnostics: false, isolatedModules: true }] },
  moduleNameMapper: {
    '^@prisma/client$': ${JSON.stringify(join(dir, 'shim-client.cjs'))},
    '^@prisma/adapter-pg$': ${JSON.stringify(join(dir, 'shim-adapter.cjs'))},
    '^@bymax-one/nest-ai-tokens/shared$': ${JSON.stringify(join(dist, 'shared/index.cjs'))},
    '^@bymax-one/nest-ai-tokens/prices$': ${JSON.stringify(join(dist, 'prices/index.cjs'))},
    '^@bymax-one/nest-ai-tokens/prisma$': ${JSON.stringify(join(dist, 'prisma/index.cjs'))},
    '^@bymax-one/nest-ai-tokens/redis$': ${JSON.stringify(join(dist, 'redis/index.cjs'))},
    '^@bymax-one/nest-ai-tokens$': ${JSON.stringify(join(dist, 'server/index.cjs'))},
  },
  testTimeout: 120000,
  maxWorkers: 1,
  forceExit: true,
}
`,
  )
}

/** Fails the process with a message and the tail of the output that explains it. */
function fail(message, output = '') {
  console.error(`✗ ${message}`)
  if (output) console.error(output.slice(-1200))
  process.exit(1)
}

const name = process.argv[2]
const cell = CELLS[name]
if (cell === undefined) fail(`unknown cell "${String(name)}"; expected one of ${Object.keys(CELLS).join(', ')}`)
if (!existsSync(join(ROOT, 'dist/prisma/index.cjs'))) fail('dist/ is missing — run `pnpm build` first')
for (const spec of SPECS) if (!existsSync(join(ROOT, `test/e2e/${spec}.e2e-spec.ts`))) fail(`test/e2e/${spec}.e2e-spec.ts is missing`)

const dir = join(WORK, name)
rmSync(dir, { recursive: true, force: true })
mkdirSync(join(dir, 'prisma'), { recursive: true })
const started = Date.now()
console.log(`Prisma matrix: ${name} (Prisma ${cell.version}, generator ${cell.generator}${cell.custom ? ' with a custom output' : ''})`)

writeFileSync(join(dir, 'package.json'), JSON.stringify({ name, private: true, version: '0.0.0' }))
const packages = [`@prisma/client@${cell.version}`, `prisma@${cell.version}`, ...(cell.major === 7 ? [`@prisma/adapter-pg@${cell.version}`] : [])]
let result = run('npm', ['install', '--save-exact', '--no-audit', '--no-fund', '--silent', ...packages], dir)
if (result.status !== 0) fail('installing the Prisma packages failed', result.stderr || result.stdout)

writeFileSync(join(dir, 'prisma/schema.prisma'), schemaOf(cell))
if (cell.major === 7) {
  writeFileSync(
    join(dir, 'prisma.config.ts'),
    "import { defineConfig } from 'prisma/config'\nexport default defineConfig({ schema: './prisma/schema.prisma', datasource: { url: 'postgresql://localhost:5432/x?schema=public' } })\n",
  )
}
result = run(join(dir, 'node_modules/.bin/prisma'), ['generate'], dir, { DATABASE_URL: 'postgresql://localhost:5432/x', CHECKPOINT_DISABLE: '1' })
if (result.status !== 0) fail('prisma generate failed', result.stderr || result.stdout)

writeHarness(dir, cell)
const report = join(dir, 'jest-result.json')
result = run(join(ROOT, 'node_modules/.bin/jest'), ['--config', join(dir, 'jest.config.cjs'), '--json', '--outputFile', report], ROOT)
if (!existsSync(report)) fail('the specs did not run', result.stderr)

const summary = JSON.parse(readFileSync(report, 'utf8'))
const failed = summary.testResults.flatMap((suite) => suite.assertionResults.filter((test) => test.status !== 'passed').map((test) => `${test.ancestorTitles.join(' > ')} > ${test.title}`))
const broken = summary.testResults.filter((suite) => suite.assertionResults.length === 0).map((suite) => suite.message.slice(0, 400))
const seconds = Math.round((Date.now() - started) / 1000)
console.log(`${name}: ${summary.numPassedTestSuites}/${summary.numTotalTestSuites} suites, ${summary.numPassedTests}/${summary.numTotalTests} tests, ${seconds} s`)
for (const line of failed.slice(0, 20)) console.error(`  ✗ ${line}`)
for (const line of broken.slice(0, 3)) console.error(`  ✗ suite did not run: ${line}`)
if (result.status !== 0 || failed.length > 0 || broken.length > 0) fail(`${name} failed`)
console.log(`✓ ${name} passes`)
